DOMAIN_META = {
    "work": {"title": "仕事運", "text_key": 2, "action_key": 3, "salt": "work"},
    "money": {"title": "金運", "text_key": 4, "action_key": 5, "salt": "money"},
    "relations": {"title": "対人運", "text_key": 6, "action_key": 7, "salt": "relations"},
}


def _date_key(now: Any = None) -> str:
    if isinstance(now, datetime):
        return now.date().isoformat()
    if isinstance(now, date):
        return now.isoformat()
    return datetime.now().date().isoformat()


def build_neko_domain_iching(
    birthdate: str | None,
    neko_name: str = "猫",
    domain: str = "work",
    now: Any = None,
) -> Dict[str, Any]:
    """指定分野について、長く読める性質として安定した1卦を選ぶ。"""
    meta = DOMAIN_META.get(domain)
    if not meta:
        raise ValueError(f"unsupported neko iching domain: {domain}")

    seed = f"neko-domain-iching-v2|{meta['salt']}|{birthdate or ''}|{neko_name}"
    digest = hashlib.sha256(seed.encode("utf-8")).digest()
    index = int.from_bytes(digest[:8], "big") % 64
    row = ICHING_DOMAIN_64[index]
    name, theme = row[0], row[1]
    text = row[meta["text_key"]]
    action = row[meta["action_key"]]
    number = index + 1

    return {
        "domain": domain,
        "domain_title": meta["title"],
        "number": number,
        "name": name,
        "theme": theme,
        "text": text,
        "action": action,
        "label": f"第{number}卦 {name} - {theme}",
        "cat_line": f"{neko_name}のひげが{meta['title']}に選んだ卦は「{name}」にゃ。",
    }


def build_neko_domain_ichings(
    birthdate: str | None,
    neko_name: str = "猫",
    now: Any = None,
) -> Dict[str, Dict[str, Any]]:
    """仕事運・金運・対人運をまとめて返す。"""
    return {
        key: build_neko_domain_iching(birthdate, neko_name, key, now=now)
        for key in ("work", "money", "relations")
    }
